package com.ragpipeline.service; import com.ragpipeline.model.Document; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; class ChunkingServiceTest {@Test void createsOrderedChunks(){var s=new ChunkingService();s.size=20;s.overlap=2;var result=s.chunk(Document.builder().rawContent("One sentence. Two sentence. Three sentence.").chunkingStrategy("RECURSIVE").build());assertFalse(result.isEmpty());assertEquals(0,result.getFirst().getChunkIndex());}}
